"use strict";

const { AsyncLocalStorage } = require("async_hooks");

module.exports = async function runAsyncLocalStorageProbe() {
  const storage = new AsyncLocalStorage();
  const seen = [];

  await storage.run({ label: "root" }, async () => {
    seen.push(storage.getStore().label);
    await Promise.resolve();
    await storage.run({ label: "child" }, async () => {
      seen.push(storage.getStore().label);
      await new Promise((resolve) => {
        setTimeout(() => {
          seen.push(storage.getStore().label === "child" ? "timer" : "timer-lost");
          resolve();
        }, 0);
      });
    });
    seen.push(storage.getStore().label === "root" ? "promise" : "promise-lost");
  });

  return seen;
};
